function validate([maxTime, edges, passingFees]) {
  if (!Number.isInteger(maxTime) || maxTime < 1 || maxTime > 1000) return 'maxTime is between 1 and 1000.';
  const n = passingFees.length;
  if (n < 2 || n > 1000) return 'passingFees needs 2 to 1000 cities.';
  if (passingFees.some(f => !Number.isInteger(f) || f < 1 || f > 1000)) return 'Each passing fee is between 1 and 1000.';
  if (edges.length < n - 1 || edges.length > 1000) return 'edges needs between n - 1 and 1000 roads.';
  const parent = Array.from({ length: n }, (_, i) => i);
  const find = (v) => { while (parent[v] !== v) { parent[v] = parent[parent[v]]; v = parent[v]; } return v; };
  let parts = n;
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 3) return 'Each road is [x, y, time].';
    const [x, y, time] = edge;
    if (!Number.isInteger(x) || !Number.isInteger(y) || x < 0 || y < 0 || x >= n || y >= n) return 'Road ends must be cities 0 to n - 1.';
    if (x === y) return 'A road cannot join a city to itself.';
    if (!Number.isInteger(time) || time < 1 || time > 1000) return 'Each road takes 1 to 1000 minutes.';
    const a = find(x), b = find(y);
    if (a !== b) { parent[a] = b; parts--; }
  }
  if (parts !== 1) return 'Every city must be reachable from every other.';
  return null;
}

