function minCost(maxTime, edges, passingFees) {
  const n = passingFees.length;
  const graph = Array.from({ length: n }, () => []);
  for (const [x, y, time] of edges) {
    graph[x].push([y, time]);
    graph[y].push([x, time]);
  }
  const minTime = new Array(n).fill(Infinity);
  minTime[0] = 0;
  const heap = [];
  const push = (item) => {
    heap.push(item);
    let i = heap.length - 1;
    while (i > 0 && heap[(i - 1) >> 1][0] > heap[i][0]) {
      const parent = (i - 1) >> 1;
      [heap[parent], heap[i]] = [heap[i], heap[parent]];
      i = parent;
    }
  };
  const pop = () => {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length > 0) {
      heap[0] = last;
      let i = 0;
      for (;;) {
        const left = 2 * i + 1;
        const right = left + 1;
        let smallest = i;
        if (left < heap.length && heap[left][0] < heap[smallest][0]) smallest = left;
        if (right < heap.length && heap[right][0] < heap[smallest][0]) smallest = right;
        if (smallest === i) break;
        [heap[smallest], heap[i]] = [heap[i], heap[smallest]];
        i = smallest;
      }
    }
    return top;
  };
  push([passingFees[0], 0, 0]);
  while (heap.length > 0) {
    const [cost, time, city] = pop();
    if (city === n - 1) return cost;
    for (const [next, travel] of graph[city]) {
      const arrival = time + travel;
      if (arrival > maxTime || arrival >= minTime[next]) continue;
      minTime[next] = arrival;
      push([cost + passingFees[next], arrival, next]);
    }
  }
  return -1;
}

