function minCost(maxTime, edges, passingFees) {
  // best[t][v]: cheapest fee total of a route that is in city v after exactly t minutes.
  const n = passingFees.length;
  const best = Array.from({ length: maxTime + 1 }, () => new Array(n).fill(Infinity));
  best[0][0] = passingFees[0];
  for (let t = 0; t <= maxTime; t++) {
    for (const [x, y, w] of edges) {
      if (t + w > maxTime) continue;
      if (best[t][x] + passingFees[y] < best[t + w][y]) best[t + w][y] = best[t][x] + passingFees[y];
      if (best[t][y] + passingFees[x] < best[t + w][x]) best[t + w][x] = best[t][y] + passingFees[x];
    }
  }
  let answer = Infinity;
  for (let t = 0; t <= maxTime; t++) answer = Math.min(answer, best[t][n - 1]);
  return answer === Infinity ? -1 : answer;
}

