function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? int(200, 1000) : int(2, 6);
  const m = large ? 1000 : Math.min(1000, int(n - 1, n + 4));
  const maxWeight = large ? int(3, 40) : int(1, 10);
  const maxFee = large ? 1000 : int(1, 20);
  // Random labels so that 0 and n - 1 land anywhere in the tree.
  const label = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) { const j = int(0, i); [label[i], label[j]] = [label[j], label[i]]; }
  const edges = [];
  for (let i = 1; i < n; i++) edges.push([label[i], label[int(0, i - 1)], int(1, maxWeight)]);
  while (edges.length < m) {
    const x = int(0, n - 1), y = int(0, n - 1);
    if (x !== y) edges.push([x, y, int(1, maxWeight)]);
  }
  for (let i = edges.length - 1; i > 0; i--) { const j = int(0, i); [edges[i], edges[j]] = [edges[j], edges[i]]; }
  const passingFees = Array.from({ length: n }, () => int(1, maxFee));
  const maxTime = large ? int(20, 1000) : int(1, 30);
  return [maxTime, edges, passingFees];
}
